 11	public static class SliceApp
 12	{
 13	    public static int Run(string[] args, TextWriter stderr, Stream outputStream)
 14	    {
 15	        if (args.Length < 3)
 16	        {
 17	            WriteUsage(stderr);
 18	            return 1;
 19	        }
 20	
 21	        try
 22	        {
 23	            if (string.Equals(args[1], "select", StringComparison.Ordinal))
 24	            {
 25	                if (args.Length != 3)
 26	                {
 27	                    WriteUsage(stderr);
 28	                    return 1;
 29	                }
 30	
 31	                var selectedColumns = args[2]
 32	                    .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
 33	                CsvRoundTripper.WriteSelectedColumns(args[0], selectedColumns, outputStream);
 34	            }
 35	            else if (string.Equals(args[1], "where", StringComparison.Ordinal))
 36	            {
 37	                var expression = string.Join(' ', args.Skip(2));
 38	                CsvRoundTripper.WriteFilteredRows(args[0], expression, outputStream);
 39	            }
 40	            else if (string.Equals(args[1], "sort", StringComparison.Ordinal))
 41	            {
 42	                if (args.Length is not 3 and not 4)
 43	                {
 44	                    WriteUsage(stderr);
 45	                    return 1;
 46	                }
 47	
 48	                var columnName = args[2];
 49	                var direction = args.Length == 4 ? args[3] : "asc";
 50	                CsvRoundTripper.WriteSortedRows(args[0], columnName, direction, outputStream);
 51	            }
 52	            else
 53	            {
 54	                WriteUsage(stderr);
 55	                return 1;
 56	            }
 57	
 58	            return 0;
 59	        }
 60	        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException or InvalidOperationException)
 61	        {
 62	            stderr.WriteLine(ex.Message);
 63	            return 1;
 64	        }
 65	    }
