 75	public static class CsvRoundTripper
 76	{
 77	    public static void WriteSelectedColumns(string path, IReadOnlyList<string> selectedColumns, Stream output)
 78	    {
 79	        using var reader = new StreamReader(File.OpenRead(path));
 80	        using var writer = new StreamWriter(output, leaveOpen: true)
 81	        {
 82	            NewLine = Environment.NewLine
 83	        };
 84	
 85	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
 86	        var headers = ParseCsvLine(headerLine);
 87	        var headerIndexes = headers
 88	            .Select((header, index) => new { header, index })
 89	            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);
 90	
 91	        var selectedIndexes = selectedColumns
 92	            .Select(columnName => headerIndexes.TryGetValue(columnName, out var index)
 93	                ? index
 94	                : throw new InvalidOperationException($"Column not found: {columnName}"))
 95	            .ToArray();
 96	
 97	        writer.WriteLine(string.Join(",", selectedColumns));
 98	
 99	        string? line;
100	        while ((line = reader.ReadLine()) is not null)
101	        {
102	            if (line.Length == 0)
103	            {
104	                writer.WriteLine();
105	                continue;
106	            }
107	
108	            var values = ParseCsvLine(line);
109	            var projectedValues = selectedIndexes.Select(index => index < values.Count ? values[index] : string.Empty);
110	            writer.WriteLine(string.Join(",", projectedValues));
111	        }
112	
113	        writer.Flush();
114	    }
