116	    public static void WriteFilteredRows(string path, string expression, Stream output)
117	    {
118	        var filter = ParseComparisonExpression(expression);
119	
120	        using var reader = new StreamReader(File.OpenRead(path));
121	        using var writer = new StreamWriter(output, leaveOpen: true)
122	        {
