124	        };
125	
126	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
127	        var headers = ParseCsvLine(headerLine);
128	        var headerIndexes = headers
129	            .Select((header, index) => new { header, index })
130	            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);
131	
132	        if (!headerIndexes.TryGetValue(filter.ColumnName, out var filterColumnIndex))
133	        {
134	            throw new InvalidOperationException($"Column not found: {filter.ColumnName}");
135	        }
136	
137	        writer.WriteLine(headerLine);
138	
139	        string? line;
140	        while ((line = reader.ReadLine()) is not null)
141	        {
142	            if (line.Length == 0)
