158	    public static void WriteSortedRows(string path, string columnName, string direction, Stream output)
159	    {
160	        var descending = ParseSortDirection(direction);
161	
162	        using var reader = new StreamReader(File.OpenRead(path));
163	        using var writer = new StreamWriter(output, leaveOpen: true)
164	        {
165	            NewLine = Environment.NewLine
166	        };
167	
168	        var headerLine = reader.ReadLine() ?? throw new InvalidOperationException("CSV file is empty");
169	        var headers = ParseCsvLine(headerLine);
170	        var headerIndexes = headers
171	            .Select((header, index) => new { header, index })
172	            .ToDictionary(x => x.header, x => x.index, StringComparer.Ordinal);
173	
174	        if (!headerIndexes.TryGetValue(columnName, out var sortColumnIndex))
175	        {
176	            throw new InvalidOperationException($"Column not found: {columnName}");
177	        }
178	
179	        var rows = new List<SortableRow>();
180	        var rowIndex = 0;
181	        var allNumeric = true;
182	
183	        string? line;
184	        while ((line = reader.ReadLine()) is not null)
185	        {
186	            if (line.Length == 0)
187	            {
188	                continue;
189	            }
190	
191	            var values = ParseCsvLine(line);
192	            var sortValue = GetValue(values, sortColumnIndex);
193	            if (!TryParseNumber(sortValue, out var numericSortValue))
194	            {
195	                allNumeric = false;
196	            }
197	
198	            rows.Add(new SortableRow(
199	                line,
200	                sortValue,
201	                numericSortValue,
202	                rowIndex++));
203	        }
204	
205	        writer.WriteLine(headerLine);
206	
207	        IEnumerable<SortableRow> orderedRows;
208	        if (allNumeric)
209	        {
210	            orderedRows = descending
211	                ? rows.OrderByDescending(row => row.NumericSortValue).ThenBy(row => row.OriginalIndex)
212	                : rows.OrderBy(row => row.NumericSortValue).ThenBy(row => row.OriginalIndex);
213	        }
214	        else
215	        {
216	            orderedRows = descending
217	                ? rows.OrderByDescending(row => row.SortValue, StringComparer.Ordinal).ThenBy(row => row.OriginalIndex)
218	                : rows.OrderBy(row => row.SortValue, StringComparer.Ordinal).ThenBy(row => row.OriginalIndex);
219	        }
